// Run with: node test.js
// Checks the conjugation engine against known paradigms, then runs every
// Russian verb in verbs.js through it to catch crashes and malformed output.
// In the verb keys below "́" stands for the stress mark (U+0301); it is converted to
// the real combining accent when this file is written, so keys read 'чита́ть:i'
// (infinitive with its stress mark, a colon, the aspect).
const { conjugate, NONE } = require('./conjugate.js');
const { VERBS } = require('./verbs.js');
const { createReport } = require('../shared/test-kit.js');

const FORM_KEYS = ['pres', 'past', 'fut', 'cond', 'imp', 'impNeg', 'ger', 'part'];
const STRESS = '\u0301';
const dashes = Array(6).fill(NONE).join(', ');
const S = text => text.split(' ').join(', '); // 'a b c' -> 'a, b, c'

// P({...}) describes a whole paradigm from its principal parts; the eight tenses are
// then written out by hand-made rules here (not taken from the engine):
//   pres  six present forms (imperfective)       fut   six simple-future forms (perfective)
//   past  masculine, feminine, neuter, plural    imp   the ты form, or null for "no imperative"
//   you2  the вы imperative if it is not imp + те   ger / part  one string, or undefined to skip
const P = spec => ({ whole: true, ...spec });

function expand(key, spec) {
  const [word, aspect] = key.split(':');
  const inf = word.split(STRESS).join('');
  const perfective = aspect === 'p';
  const six = text => text.split(' ').join(', ');
  const [m, f, n, pl] = spec.past.split(' ');
  const out = {};
  const presForms = (spec.pres || spec.fut).split(' ');
  out.pres = perfective ? dashes : six(spec.pres);
  out.past = [`${m} / ${f}`, `${m} / ${f}`, `${m} / ${f} / ${n}`, pl, pl, pl].join(', ');
  out.fut = perfective || spec.fut ? six(spec.fut) : ['буду', 'будешь', 'будет', 'будем', 'будете', 'будут'].map(a => `${a} ${inf}`).join(', ');
  out.cond = [`${m} бы / ${f} бы`, `${m} бы / ${f} бы`, `${m} бы / ${f} бы / ${n} бы`, `${pl} бы`, `${pl} бы`, `${pl} бы`].join(', ');
  if (spec.imp === null) {
    out.imp = dashes;
    out.impNeg = dashes;
  } else {
    const you2 = spec.you2 || spec.imp + 'те';
    const we = perfective ? presForms[3] : inf;
    out.imp = [spec.imp, spec.imp, spec.imp, `давайте ${we}`, you2, you2].join(', ');
    out.impNeg = perfective ? dashes
      : [`не ${spec.imp}`, `не ${spec.imp}`, `не ${spec.imp}`, `давайте не ${inf}`, `не ${you2}`, `не ${you2}`].join(', ');
  }
  if (spec.ger !== undefined) out.ger = Array(6).fill(spec.ger).join(', ');
  if (spec.part !== undefined) out.part = Array(6).fill(spec.part).join(', ');
  return out;
}

